'use strict';
const Q=Qualia,$=id=>document.getElementById(id),fmt=x=>Number(x).toFixed(3);
let state={version:1,raw:Q.base(),agents:[Q.agent(),Q.agent()],domain:0,pair:null,model:'hand',seed:42,memories:[0,0],sequence:[],alignment:null,winner:null};
let busy=false,toastTimer;
const names=['Red ↔ green','Saturation','Illumination','Shadow','Light angle','Object · apple −1 / ball +1','Pitch · low ↔ high','Loudness','Texture · smooth ↔ rough','Temperature · cool ↔ warm','Taste · bitter ↔ sweet','Scent · earthy ↔ floral','Context','Prior association','Emotional association','Previous-state trace'];
const domains=['Vision','Sound','Touch','Taste','Smell'];
const primary=[0,6,9,10,11];
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5500);}
function switchTab(tab){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.id==='tab-'+tab));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('pageTitle').textContent={lab:'Experiment studio',learning:'Learning & alignment',search:'Behavioral twins',research:'Research notebook',monty:'Sensorimotor lab',theory:'Theory workbench',orch:'Orch OR explorer'}[tab];}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function invalid(){state.alignment=null;state.winner=null;$('alignmentResult').textContent='Settings changed. Run alignment again to recalibrate.';$('searchResult').textContent='Settings changed. Run a new search.';$('loadWinner').hidden=true;$('searchStatus').textContent='No current search result.';$('ablations').textContent='Run ablations on the current experience.';}
function nets(){return state.model==='learned'?state.pair:null;}
function evalPair(raw=state.raw,ablate=[]){return state.agents.map((a,i)=>{const x=raw.slice();x[15]=Q.clamp(x[15]+state.memories[i]);return Q.evaluate(x,a,nets()?.[i?'b':'a'],state.domain,ablate);});}
function slider(i){const min=[1,2,3,7].includes(i)?0:-1;return `<div class="slider"><label class="sliderlabel" for="x${i}"><span>${names[i]}</span><output id="out${i}">${state.raw[i].toFixed(2)}</output></label><input id="x${i}" data-input="${i}" type="range" min="${min}" max="1" step="0.01" value="${state.raw[i]}"></div>`;}
function controls(){const p=primary[state.domain];$('primaryControls').innerHTML=slider(p)+(state.domain===0?slider(1):state.domain===1?slider(7):'');$('physicalControls').innerHTML=[2,3,4,5].map(slider).join('');$('sensoryControls').innerHTML=[6,7,8,9,10,11].filter(i=>i!==p&&!(state.domain===1&&i===7)).map(slider).join('');$('contextControls').innerHTML=[12,13,14,15].map(slider).join('');document.querySelectorAll('[data-input]').forEach(el=>el.oninput=()=>{state.raw[+el.dataset.input]=+el.value;$('out'+el.dataset.input).textContent=(+el.value).toFixed(2);$('stimulusName').textContent='Custom '+domains[state.domain].toLowerCase()+' experience';invalid();render();});}
function agentsUI(){ $('agents').innerHTML=state.agents.map((a,i)=>`<section class="panel agent ${i?'b':''}"><div class="paneltitle"><h2>Agent ${i?'B':'A'}</h2><span class="tag">${i?'COMPARISON':'REFERENCE'}</span></div><div class="report" id="report${i}"></div><div class="behavior"><span id="confidence${i}"></span><span class="action" id="action${i}"></span></div><details><summary>History & interventions</summary>${[['offset','Context offset',-1,1],['memory','Memory association',-1,1],['emotion','Emotion offset',-1,1],['senses','Nonvisual signal gain',0,2]].map(([key,name,min,max])=>`<div class="slider"><label class="sliderlabel" for="a${i}${key}">${name}<output id="av${i}${key}">${a[key].toFixed(2)}</output></label><input id="a${i}${key}" data-agent="${i}" data-prop="${key}" type="range" min="${min}" max="${max}" step=".01" value="${a[key]}"></div>`).join('')}<div class="gates">${Object.keys(Q.groups).map(g=>`<button data-gate="${g}" data-agent="${i}" class="${a.gates[g]?'':'off'}" aria-pressed="${a.gates[g]}">${g==='senses'?'nonvisual senses':g}</button>`).join('')}</div>${[['invert','Invert hidden unit 1'],['compensate','Compensate the readout'],['labels','Swap report endpoint labels']].map(([key,label])=>`<label class="check"><input type="checkbox" data-agent="${i}" data-prop="${key}" ${a[key]?'checked':''}>${label}</label>`).join('')}<p class="subtle">Compensation only matters when inversion is enabled. These are controlled remappings.</p></details></section>`).join('');document.querySelectorAll('[data-prop]').forEach(el=>el.oninput=()=>{const a=state.agents[+el.dataset.agent];a[el.dataset.prop]=el.type==='checkbox'?el.checked:+el.value;const out=$('av'+el.dataset.agent+el.dataset.prop);if(out)out.textContent=(+el.value).toFixed(2);invalid();render();});document.querySelectorAll('[data-gate]').forEach(el=>el.onclick=()=>{const a=state.agents[+el.dataset.agent];a.gates[el.dataset.gate]=!a.gates[el.dataset.gate];el.classList.toggle('off',!a.gates[el.dataset.gate]);el.setAttribute('aria-pressed',a.gates[el.dataset.gate]);invalid();render();});}
function render(){const [a,b]=evalPair(),c=Q.compare(a,b);[a,b].forEach((v,i)=>{$('report'+i).textContent=v.report;$('confidence'+i).textContent=(100*v.confidence).toFixed(1)+'% confidence';$('action'+i).textContent=v.action;});$('bars').innerHTML=a.h.map((v,j)=>`<div class="barrow"><span>h${j+1}</span><div class="bartrack">${[v,b.h[j]].map((n,i)=>`<i class="bar ${i?'b':''}" style="left:${50+Math.min(n,0)*50}%;width:${Math.abs(n)*50}%"></i>`).join('')}</div><span>${v.toFixed(2)} / ${b.h[j].toFixed(2)}</span></div>`).join('');$('distance').textContent=fmt(c.distance);$('cosine').textContent=fmt(c.cosine);$('agreement').textContent=c.same?'Match':'Different';$('agreement').style.color=c.same?'#a9e4ed':'#ffad9b';$('modelBadge').textContent=state.model==='learned'?'Learned · '+state.pair.history:'Transparent model';$('swatch').style.background=state.domain===0?`hsl(${(1-state.raw[0])*60} ${state.raw[1]*90}% ${25+state.raw[2]*30}%)`:'#4c9bae';$('stimulusCaption').textContent=domains[state.domain]+' report · shared raw signal';document.querySelectorAll('[data-domain]').forEach(el=>el.classList.toggle('selected',+el.dataset.domain===state.domain));}
function fullRender(){controls();agentsUI();render();renderSequence();$('model').value=state.model;$('model').options[1].disabled=!state.pair;$('seed').value=state.seed;}
document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{state.domain=+b.dataset.domain;invalid();controls();render();});
$('preset').onchange=()=>{const preset=$('preset').value;state.raw=Q.base();if(preset==='ball')state.raw[5]=1;if(preset==='tone'){state.domain=1;state.raw[6]=.8;state.raw[7]=.8;}else if(preset==='touch'){state.domain=2;state.raw[9]=.8;state.raw[8]=.6;}else if(preset==='taste'){state.domain=3;state.raw[10]=.8;}else if(preset==='smell'){state.domain=4;state.raw[11]=.8;}else if(preset==='neutral'){state.raw=Array(16).fill(0);state.raw[1]=.8;state.raw[2]=.65;}else state.domain=0;$('stimulusName').textContent=$('preset').selectedOptions[0].textContent;invalid();controls();render();};
$('reset').onclick=()=>{state.agents=[Q.agent(),Q.agent()];state.memories=[0,0];state.sequence=[];if(state.pair)state.pair.b=Q.clone(state.pair.a);invalid();fullRender();notify('Agents now share weights, settings, and memory. The current stimulus is preserved.');};
$('randomB').onclick=()=>{const r=Q.rng(state.seed+17+state.sequence.length);['offset','memory','emotion'].forEach(k=>state.agents[1][k]=r()*2-1);state.agents[1].senses=.5+r();invalid();agentsUI();render();notify('B history randomized reproducibly. The shared stimulus is unchanged.');};
function renderSequence(){$('timeline').innerHTML=state.sequence.length?state.sequence.slice(-20).map((s,i)=>`<div class="sequenceitem"><b>${s.step}. ${domains[s.domain]}</b><br>A: ${s.reports[0]} · ${s.actions[0]}<br>B: ${s.reports[1]} · ${s.actions[1]}<br>Distance ${fmt(s.distance)}</div>`).join(''):'<span class="subtle">No experiences presented. Slider previews do not advance memory.</span>';}
$('step').onclick=()=>{const out=evalPair(),c=Q.compare(...out);state.sequence.push({step:state.sequence.length+1,domain:state.domain,raw:state.raw.slice(),reports:out.map(x=>x.report),actions:out.map(x=>x.action),distance:c.distance,memoriesBefore:state.memories.slice()});state.memories=out.map((o,i)=>Q.clamp(.65*state.memories[i]+.35*o.h[6]));invalid();renderSequence();render();notify('Experience recorded. The preview now includes the updated memory trace.');};
$('clearMemory').onclick=()=>{state.memories=[0,0];state.sequence=[];invalid();renderSequence();render();};
$('ablate').onclick=()=>{const results=[['baseline',[]],...Object.keys(Q.groups).map(g=>[g,[g]]),['all five',Object.keys(Q.groups)]].map(([name,ab])=>({name,...Q.compare(...evalPair(state.raw,ab))}));const base=results[0].distance;$('ablations').innerHTML=results.map(r=>`<div class="ablationrow"><span>${r.name==='baseline'?'Baseline':'Remove '+r.name}</span><div class="ablationtrack"><i style="width:${r.distance/2*100}%"></i></div><span>${fmt(r.distance)} · ${r.same?'match':'different'}<br><small>Δ ${r.distance-base>=0?'+':''}${fmt(r.distance-base)}</small></span></div>`).join('')+'<p class="subtle">RMS distance, range 0–2. Negative Δ means convergence relative to baseline. Zeroing channels is a model intervention and may be outside the training distribution.</p>';};
function lock(on){busy=on;document.querySelectorAll('button,input,select').forEach(el=>{el.disabled=on;});if(!on)$('model').options[1].disabled=!state.pair;}
$('train').onclick=async()=>{if(busy)return;const seed=+$('seed').value;if(!Number.isInteger(seed)||seed<1||seed>2147483647){notify('Use an integer seed between 1 and 2147483647.');return;}lock(true);try{state.seed=seed;$('trainingStatus').textContent='Training both agents…';const pair=await Q.trainPair({seed,history:$('history').value,epochs:+$('epochs').value},p=>{$('trainingProgress').value=p;});state.pair=pair;state.model='learned';state.agents=[Q.agent(),Q.agent()];state.memories=[0,0];state.sequence=[];invalid();const r=Q.rng(seed+9001),accuracy=[0,0];for(let i=0;i<300;i++){const raw=Q.sample(r),ys=Q.targets(Q.effective(raw,Q.agent()));for(let j=0;j<2;j++){const out=Q.evaluate(raw,Q.agent(),pair[j?'b':'a'],state.domain);if(out.report===Q.labels[state.domain][ys[state.domain]])accuracy[j]++;}}$('validation').textContent=`Fresh common-distribution ${domains[state.domain].toLowerCase()} accuracy: A ${(accuracy[0]/3).toFixed(1)}%, B ${(accuracy[1]/3).toFixed(1)}% (300 examples; canonical labels, including for inverted-label B). This is synthetic task accuracy, not a consciousness score.`;$('trainingStatus').textContent=`Trained ${pair.epochs} epochs × ${pair.samples} experiences per agent. Seed ${seed}. Training reset agent interventions and sequence memory.`;fullRender();notify('Both networks trained. The learned model is active.');}catch(e){notify(e.message);$('trainingStatus').textContent='Training failed.';}finally{lock(false);}};
$('model').onchange=()=>{state.model=$('model').value;invalid();render();};
$('align').onclick=()=>{try{state.alignment=Q.alignment(nets(),state.agents,state.seed,state.domain);const a=state.alignment;$('alignmentResult').innerHTML=`<div class="metrics"><div><span>Raw held-out RMS</span><strong>${fmt(a.raw)}</strong></div><div><span>Aligned held-out RMS</span><strong>${fmt(a.aligned)}</strong></div><div><span>Behavior agreement</span><strong>${(a.agreement*100).toFixed(1)}%</strong></div></div><p>192 calibration + 192 separate evaluation experiences. Fresh synthetic previous-state inputs; current sequence memory is not added to this calibration.</p>`;notify('Alignment fitted and evaluated on separate experiences.');}catch(e){notify(e.message);}};
$('search').onclick=async()=>{if(busy)return;const metric=$('searchMetric').value;if(metric==='aligned'&&!state.alignment){notify('Run alignment in Learning & alignment first.');return;}lock(true);try{const n=+$('cases').value,strict=$('strict').checked,r=Q.rng(state.seed+7103);let best=null,matches=0;for(let i=0;i<n;i++){const raw=Q.sample(r),out=evalPair(raw),c=Q.compare(...out);if(c.same&&(!strict||c.probabilityGap<=.05)){matches++;const distance=metric==='aligned'?Q.rms(out[0].h,Q.aligned(out[1].h,state.alignment.map)):c.distance;if(!best||distance>best.score)best={raw,out,comparison:c,score:distance,metric};}if(i%250===0){$('searchProgress').value=(i+1)/n;$('searchStatus').textContent=`Examined ${(i+1).toLocaleString()} / ${n.toLocaleString()} experiences…`;await new Promise(r=>setTimeout(r,0));}}$('searchProgress').value=1;$('searchStatus').textContent=`${n.toLocaleString()} candidates · ${matches.toLocaleString()} matches (${(100*matches/n).toFixed(1)}%) · seed ${state.seed+7103}`;state.winner=best;state.lastSearch={n,matches,strict,metric,seed:state.seed+7103};$('loadWinner').hidden=!best;if(best){$('searchResult').innerHTML=`<div class="metrics"><div><span>${metric==='aligned'?'Aligned':'Raw'} RMS distance</span><strong>${fmt(best.score)}</strong></div><div><span>Probability gap</span><strong>${fmt(best.comparison.probabilityGap)}</strong></div></div><p>Both report <strong>${best.out[0].report}</strong> and <strong>${best.out[0].action}</strong>.</p><p>A confidence ${(100*best.out[0].confidence).toFixed(1)}% · B confidence ${(100*best.out[1].confidence).toFixed(1)}%.</p><p>Load this case to inspect all channels and run paired ablations.</p>`;}else $('searchResult').textContent='No matches under these conditions. Try the coarse criterion, a different history, or a larger sample. No winner has been invented.';}catch(e){notify(e.message);}finally{lock(false);}};
$('loadWinner').onclick=()=>{if(!state.winner)return;state.raw=state.winner.raw.slice();controls();render();switchTab('lab');$('stimulusName').textContent='Behavioral twin · discovered case';$('ablations').textContent='Run ablations on this discovered case.';};
function download(name,data){const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>download('qualia-lab-session.json',JSON.stringify(state,null,2));
function validateSession(s){if(!s||s.version!==1||!Array.isArray(s.raw)||s.raw.length!==16||!s.raw.every((x,i)=>Number.isFinite(x)&&x>=([1,2,3,7].includes(i)?0:-1)&&x<=1))throw Error('Invalid experience vector.');if(!Number.isInteger(s.domain)||s.domain<0||s.domain>4||!Number.isInteger(s.seed)||s.seed<1||s.seed>2147483647||!['hand','learned'].includes(s.model))throw Error('Invalid session settings.');if(!Array.isArray(s.agents)||s.agents.length!==2)throw Error('Expected two agents.');for(const a of s.agents){for(const k of ['offset','memory','emotion'])if(!Number.isFinite(a[k])||Math.abs(a[k])>1)throw Error('Invalid agent history.');if(!Number.isFinite(a.senses)||a.senses<0||a.senses>2)throw Error('Invalid sensory gain.');for(const k of ['invert','compensate','labels'])if(typeof a[k]!=='boolean')throw Error('Invalid intervention.');for(const k of Object.keys(Q.groups))if(typeof a.gates?.[k]!=='boolean')throw Error('Invalid gates.');}if(!Array.isArray(s.memories)||s.memories.length!==2||!s.memories.every(x=>Number.isFinite(x)&&Math.abs(x)<=1))throw Error('Invalid memory.');if(s.pair){for(const key of ['a','b']){const net=s.pair[key];for(const [k,n,m] of [['w',8,16],['v',17,8],['d',16,8]])if(!Array.isArray(net?.[k])||net[k].length!==n||!net[k].every(r=>Array.isArray(r)&&r.length===m&&r.every(x=>Number.isFinite(x)&&Math.abs(x)<1e6)))throw Error('Invalid model matrix.');for(const [k,n] of [['b',8],['c',17],['e',16]])if(!Array.isArray(net[k])||net[k].length!==n||!net[k].every(x=>Number.isFinite(x)&&Math.abs(x)<1e6))throw Error('Invalid model bias.');}if(!['identical','different','inverted'].includes(s.pair.history))throw Error('Invalid history.');}if(s.model==='learned'&&!s.pair)throw Error('Missing trained model.');if(!Array.isArray(s.sequence)||s.sequence.length>10000||!s.sequence.every(x=>Number.isInteger(x.step)&&x.step>0&&Number.isInteger(x.domain)&&x.domain>=0&&x.domain<5&&Number.isFinite(x.distance)&&Array.isArray(x.reports)&&x.reports.length===2&&x.reports.every(v=>Q.labels.flat().includes(v))&&Array.isArray(x.actions)&&x.actions.length===2&&x.actions.every(v=>['approach','avoid'].includes(v))))throw Error('Invalid sequence.');return{version:1,raw:s.raw,agents:s.agents,domain:s.domain,pair:s.pair,model:s.model,seed:s.seed,memories:s.memories,sequence:s.sequence,alignment:null,winner:null};}
$('import').onchange=async()=>{const file=$('import').files[0];if(!file)return;try{if(file.size>8e6)throw Error('Session exceeds the 8 MB limit.');const next=validateSession(JSON.parse(await file.text()));state=next;invalid();fullRender();$('stimulusName').textContent='Imported experience';$('trainingStatus').textContent=state.pair?'Imported trained models. Re-run alignment and search as needed.':'Imported transparent-model session.';notify('Session restored. Re-run alignment and search to refresh derived results.');}catch(e){notify('Import rejected: '+e.message);}finally{$('import').value='';}};
fullRender();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_experience_comparison',description:'Read the current two-agent comparison without changing the experiment.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');const out=evalPair();return{domain:domains[state.domain],model:state.model,agents:out,comparison:Q.compare(...out)};}})).catch(()=>{});}catch{}}
